mapper.sql:
FROM user a
LEFT JOIN product b on b.user_userSeq = a.userSeq
WHERE 1=1
 AND a.userUseNy= #{shUseNy}
 AND a.userDelNy = #{shDelNy}

	AND a.regDateTime BETWEEN #{shDateStart} AND
		#{shDateEnd}

	AND a.modDateTime BETWEEN #{shDateStart} AND
		#{shDateEnd}



	AND a.userSeq = #{shValue}
	AND a.userName LIKE CONCAT('%',#{shValue},'%')

mapper.insert:
INSERT INTO user (
userName
,userUseNy
,userOrder
,userDesc
,userDelNy
,regDateTime
,modDateTime
,userGender
,userId
,userPw
,userEmail
) VALUES (
#{userName}
,#{userUseNy}
,#{userOrder}
,#{userDesc}
,0
,now()
,now()
,#{userGender}
,#{userId}
,#{userPw}
,#{userEmail}
)

	SELECT last_insert_id()

mapper.update:
UPDATE user
SET
userName = #{userName}
,userUseNy =
#{userUseNy}
,userOrder = #{userOrder}
WHERE 1=1
AND userSeq
= #{userSeq}
